/* Retrospective counts distinct seasons within one award category. */
(() => {
  const h=window.STEM_DATA.school_history;
  if(!h)return;
  const entities=new Map(h.entities.map(e=>[e.id,e]));
  const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const q=s=>document.querySelector(s);
  const kinds={school:'Школа',club:'Внешкольный клуб',community:'Самостоятельный клуб',mixed:'Несколько школ / district',unresolved:'Школьная связь неизвестна'};
  const levels={world_match:'Победа матчей · мировой финал',world_skills:'1-е место технической категории',world_judged:'Оценённая награда · мировое событие',world_division:'Победа дивизиона',world_finalist:'Финалист мировой награды',world_podium:'Призовое место · мировая категория',national_match:'Национальная победа',national_skills:'Национальный Skills',national_other:'Национальная награда',regional_match:'Победа штата / региона',regional_skills:'Техническая категория · регион',school_internal:'Внутришкольный турнир',regional_podium:'Призовое место · регион',regional_judged:'Награда штата / региона',qualification:'Квалификация на Worlds',network_match:'Победа школьной сети · страна',unresolved_stage:'Награда · уровень финала уточнить',unclassified:'Категория не установлена'};
  const prov={organizer_protocol:'Протокол организатора',school_report:'Отчёт школы',school_operator_report:'Отчёт школьной сети',season_partner_report:'Рассказ партнёра сезона'};
  const status={complete:'Полный набор выбранных FRC наград',complete_selected:'7 выбранных первых мест WRO',cancelled:'Championship отменён',awards_only:'Отдельный awards-only формат',pending:'Мировые результаты ещё впереди',protocol:'Протокол победителя FLL',report:'Сообщение участника / партнёра',case:'Выборочные результаты',not_started:'Лига ещё не существовала',archive_gap:'Архив / школьные связи не восстановлены'};
  const f={window:10,league:'FRC',kind:'',level:'',query:'',entity:''};let init=false;
  const years=()=>Array.from({length:f.window},(_,i)=>2027-f.window+i);
  const rowYears=(id,level='world_match')=>new Set(h.results.filter(r=>r.entity_id===id&&r.league==='FRC'&&r.level===level&&r.year>=2027-f.window).map(r=>r.year));
  function leaderCards(){
    const full=e=>new Set(h.results.filter(r=>r.entity_id===e.id&&r.league==='FRC'&&r.level==='world_match').map(r=>r.year)).size;
    let a=h.entities.filter(e=>full(e)>1);
    a=a.filter(e=>(!f.kind||f.kind===e.kind)&&(!f.query||(e.name+' '+e.country).toLowerCase().includes(f.query.toLowerCase())));
    a.sort((a,b)=>rowYears(b.id).size-rowYears(a.id).size||full(b)-full(a)||a.name.localeCompare(b.name));
    if(!f.kind)a=a.filter(e=>e.kind==='school');
    q('#history-leaders').innerHTML=a.map(e=>`<button class="history-leader${f.entity===e.id?' chosen':''}" data-history-entity="${safe(e.id)}" aria-pressed="${f.entity===e.id}"><span>${safe(e.country)} · ${safe(kinds[e.kind])}</span><h4>${safe(e.name)}</h4><div class="history-leader-value"><strong>${rowYears(e.id).size}</strong><span>победных сезонов<br>за ${f.window} лет</span></div><div class="history-dots" aria-label="Сезоны: ${[...rowYears(e.id)].join(', ')||'нет Championship Winner в этом окне'}">${years().map(y=>`<i class="${rowYears(e.id).has(y)?'won':y===2020||y===2021?'no-final':''}" title="${y}: ${rowYears(e.id).has(y)?'Championship Winner':y===2020||y===2021?'матчевого Championship не было':'нет Championship Winner в этом наборе'}"><span>${String(y).slice(2)}</span></i>`).join('')}</div><p>${e.kind==='school'?'Подростковая команда · для детей позже':'Внешняя программа · отдельный от школы вход'}</p></button>`).join('')||'<p class="history-empty">Для этого типа / поиска нет повторных FRC Championship Winner в извлечённом наборе. Другие награды смотрите в таблице.</p>';
  }
  function render(){
    if(!q('#school-history'))return;
    if(!init){
      const leagues=[...new Set(h.results.map(r=>r.league))].sort();
      q('#school-history').innerHTML=`<div class="history-heading"><div><p class="section-kicker">ДЕСЯТЬ ЛЕТ · ПРОВЕРЯЕМ РЕЗУЛЬТАТЫ</p><h3>Кто побеждает<br><em>снова и снова.</em></h3><p>История команды, кампус и уровень награды. Устойчивость сравниваем внутри одной лиги.</p></div><div class="history-period" role="group" aria-label="Период истории"><button data-history-window="10" aria-pressed="true">10 лет</button><button data-history-window="5" aria-pressed="false">5 лет</button><small id="history-window-label"></small></div></div>
        <div class="history-summary"><span><b>${h.results.length}</b> записей результатов</span><span><b>44</b> FRC winning-alliance entries</span><span><b>28</b> первых мест WRO</span><span>Проверено <b>${safe(h.checked)}</b></span></div>
        <p class="history-intro">Многолетнее лидерство надёжнее всего установлено по FRC. Полностью прочитаны победившие альянсы и главные Chairman / Impact награды 11 сыгранных Championship в 2017–2026. Другие лиги и связь победителей со школами исследованы частично.</p>
        <div class="history-block-title"><h4>Повторные FRC Championship Winner</h4><p>Член победившего альянса · подростковые команды · разные сезоны</p></div><div id="history-leaders" class="history-leaders"></div><p class="history-small">Цветная точка — Championship Winner. Пунктир — отменённый матчевый финал; пустая — нет такой награды в проверенном наборе. В 2017–2019 были два отдельных Championship. Это не оценка всех выступлений школы.</p>
        <div class="history-block-title"><h4>Команда → сезон → первичный источник</h4><p>Выберите школу выше или отфильтруйте таблицу.</p></div><div class="history-filters"><label>Лига<select data-history-filter="league"><option value="">Все исследованные результаты</option>${leagues.map(l=>`<option>${safe(l)}</option>`).join('')}</select></label><label>Организация<select data-history-filter="kind"><option value="">Все типы</option>${Object.entries(kinds).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Уровень награды<select data-history-filter="level"><option value="">Все уровни отдельно</option>${Object.entries(levels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Поиск<input data-history-filter="query" type="search" placeholder="Madera, Taiwan, Sprout…"></label></div><p id="history-result-count" role="status" aria-live="polite"></p><div class="history-selection" id="history-selection" hidden></div><div class="history-table-scroll" tabindex="0" aria-label="История результатов, прокручиваемая таблица"><table><caption class="sr-only">Буквальные результаты и источники, текущие фильтры</caption><thead><tr><th>Год</th><th>Школа / организация</th><th>Результат</th><th>Доказательство</th></tr></thead><tbody id="history-results"></tbody></table></div>
        <div class="history-block-title"><h4>Какие годы действительно проверены</h4><p>Охват по лигам. Пробел в архиве не означает проигрыш или отсутствие команды.</p></div><div class="history-coverage-scroll" tabindex="0" aria-label="Матрица охвата по годам"><table class="history-coverage"><thead id="history-coverage-head"></thead><tbody id="history-coverage-body"></tbody></table></div><div class="history-legend"><span><i class="complete"></i> Выбранный полный набор</span><span><i class="case"></i> Кейсы / отчёты</span><span><i class="pending"></i> Будущие результаты</span><span><i class="archive_gap"></i> Пробел</span></div><div id="history-coverage-detail" class="history-coverage-detail"></div>
        <div class="history-block-title"><h4>Что это меняет для Матвея и Оскара</h4><p>Возраст 6 / 9, будущие 10–12 и подростковая команда проверяются отдельно.</p></div><div id="history-family" class="history-family"></div><details class="school-method"><summary>Как считали сезоны и отличали титулы</summary><ul>${h.methodology.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></details><details class="school-method"><summary>Что ещё требуется для полного мирового сравнения</summary><ul>${h.gaps.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></details><div class="school-downloads"><a class="button primary" href="downloads/STEM_school_history.json" download>История и источники · JSON</a><a class="button secondary" href="downloads/STEM_school_history.csv" download>Все результаты · CSV</a><a class="button secondary" href="downloads/STEM_school_history.md" download>Анализ · текст</a></div>`;
      q('#history-family').innerHTML=h.family_routes.map((r,i)=>`<article><span>0${i+1}</span><h4>${safe(r.name)}</h4><p>${safe(r.detail)}</p><div>${r.ids.map(id=>`<button data-school-open="${id}">${safe(window.STEM_DATA.schools.find(s=>s.id===id).name)} ↗</button>`).join('')}</div></article>`).join('');
      q('#history-coverage-detail').innerHTML=h.coverage.map(c=>`<details><summary>${safe(c.name)} · ${c.status==='bounded_complete'?'полный выбранный набор':'частичный архив'}</summary><p>${safe(c.detail)}</p><div>${c.sources.map((u,i)=>`<a href="${safe(u)}" target="_blank" rel="noopener">Источник ${i+1} ↗</a>`).join('')}</div></details>`).join('');
      init=true;
    }
    q('#history-window-label').textContent=`${2027-f.window}–2026 · на ${safe(h.checked)}`;
    document.querySelectorAll('[data-history-window]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.historyWindow)===f.window)));
    q('#school-history').querySelectorAll('[data-history-filter]').forEach(x=>{if(x.value!==f[x.dataset.historyFilter])x.value=f[x.dataset.historyFilter];});
    leaderCards();
    const a=h.results.filter(r=>{const e=entities.get(r.entity_id);return r.year>=2027-f.window&&(!f.league||r.league===f.league)&&(!f.kind||e.kind===f.kind)&&(!f.level||r.level===f.level)&&(!f.entity||e.id===f.entity)&&(!f.query||JSON.stringify([e,r]).toLowerCase().includes(f.query.toLowerCase()));}).sort((a,b)=>b.year-a.year||entities.get(a.entity_id).name.localeCompare(entities.get(b.entity_id).name));
    q('#history-result-count').textContent=`Показано ${a.length} из ${h.results.filter(r=>r.year>=2027-f.window).length} записей в окне ${2027-f.window}–2026. Запись — награда команды, не число школ или победных сезонов.`;
    q('#history-selection').hidden=!f.entity;
    q('#history-selection').innerHTML=f.entity?`<strong>${safe(entities.get(f.entity).name)}</strong><button data-history-clear>Снять выбор ×</button>`:'';
    q('#history-results').innerHTML=a.map(r=>{const e=entities.get(r.entity_id);return `<tr><td>${r.year}</td><td><strong>${safe(e.name)}</strong><small>${safe(e.country)} · ${safe(kinds[e.kind])}</small><small>${safe(r.team)} ${r.team_id?'#'+safe(r.team_id):''}</small>${e.school_id?`<button data-school-open="${e.school_id}">Досье школы ↗</button>`:''}<details><summary>Связь со школой / возраст</summary><p>${safe(e.note||'Конкретная школа названа источником; язык, отбор и место требуют проверки.')}</p><p>${e.age==='primary'?'Есть младшая школьная ступень / Elementary track; возраст конкретной команды уточнить.':e.age==='unknown'?'Возраст конкретной команды не установлен.':'Подростковый результат; не доказательство команды для 6 / 9.'}</p></details></td><td><span class="history-award-level ${r.level}">${safe(levels[r.level])}</span><strong>${safe(r.award)}</strong><small>${safe(r.league)} · ${safe(r.category)}</small><small>${safe(r.stage)}</small><details><summary>Нюансы результата</summary><p>${safe(r.note)}</p></details></td><td><span>${safe(prov[r.provenance]||r.provenance)}</span><a href="${safe(r.source)}" target="_blank" rel="noopener">Проверить источник ↗</a></td></tr>`;}).join('')||'<tr><td colspan="4">Результатов для этих фильтров нет в текущем архиве.</td></tr>';
    q('#history-coverage-head').innerHTML=`<tr><th>Лига / программа</th>${years().map(y=>`<th>${y}</th>`).join('')}</tr>`;
    q('#history-coverage-body').innerHTML=h.coverage.map(c=>`<tr><th>${safe(c.name)}</th>${years().map(y=>`<td><span class="${c.years[y]}" tabindex="0" title="${safe(status[c.years[y]])}" aria-label="${safe(c.name)} ${y}: ${safe(status[c.years[y]])}">${['complete','complete_selected'].includes(c.years[y])?'✓':c.years[y]==='pending'?'◷':c.years[y]==='cancelled'||c.years[y]==='awards_only'?'∅':c.years[y]==='archive_gap'?'—':c.years[y]==='not_started'?'·':'●'}</span></td>`).join('')}</tr>`).join('');
  }
  document.addEventListener('click',ev=>{
    const b=ev.target.closest('button');if(!b)return;
    if(b.dataset.historyWindow){f.window=Number(b.dataset.historyWindow);render();}
    if(b.dataset.historyEntity){f.entity=f.entity===b.dataset.historyEntity?'':b.dataset.historyEntity;f.league='FRC';f.level='';render();q('#history-result-count').scrollIntoView({behavior:'smooth',block:'start'});}
    if(b.hasAttribute('data-history-clear')){f.entity='';render();}
  });
  document.addEventListener('change',ev=>{if(ev.target.dataset.historyFilter&&ev.target.dataset.historyFilter!=='query'){f[ev.target.dataset.historyFilter]=ev.target.value;f.entity='';render();}});
  document.addEventListener('input',ev=>{if(ev.target.dataset.historyFilter==='query'){f.query=ev.target.value;f.entity='';render();}});
  window.renderSchoolHistory=render;
})();
